#include <iostream>
#include <vector>
#include <numeric>
using namespace std;

const int MAX_DIM=33;
const long long MOD=1000000007;

struct Mat {
    long long mat[MAX_DIM][MAX_DIM];
};

Mat mat_multiply(const Mat &m1, const Mat &m2, int size) {
    Mat res = {};
    for (int i=0; i<=size; ++i)
        for (int j=0; j<=size; ++j) {
            long long sum=0;
            for (int p=0; p<=size; ++p)
                sum=(sum + m1.mat[i][p]*m2.mat[p][j])%MOD;
            res.mat[i][j]=sum;
        }
    return res;
}

int main() {
    long long n;
    int k;
    cin >> n >> k;

    Mat answer = {};
    for (int i=0; i<=k; ++i)
        answer.mat[i][i]=1;

    vector<Mat> trans(k);
    for (int p=0; p<k; ++p) {
        for (int i=0; i<=k; ++i)
            for (int j=0; j<=k; ++j)
                trans[p].mat[i][j]= (i==j || i==p) ? 1 : 0;
    }

    vector<int> digits;
    for (long long temp=n; temp>0; temp/=k)
        digits.push_back(temp%k);
    digits.push_back(0);
    partial_sum(digits.rbegin(), digits.rend(), digits.rbegin());

    for (size_t p=0; p+1<digits.size(); ++p) {
        for (int i=digits[p]-1; i>=digits[p+1]; --i)
            answer=mat_multiply(trans[i%k], answer, k);
        vector<Mat> pre(k), suf(k);
        pre[0]=trans[0];
        for (int i=1; i<k; ++i)
            pre[i]=mat_multiply(pre[i-1], trans[i], k);
        suf[k-1]=trans[k-1];
        for (int i=k-2; i>=0; --i)
            suf[i]=mat_multiply(trans[i], suf[i+1], k);
        answer=mat_multiply(suf[0], answer, k);
        for (int i=1; i<k; ++i)
            answer=mat_multiply(suf[i], pre[i-1], k);
    }

    long long total=0;
    for (int i=0; i<=k; ++i)
        total+=answer.mat[i][k];
    cout << total%MOD << endl;
    return 0;
}
